import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { organizationLogic } from 'scenes/organizationLogic'
import { isProjectNameTaken } from 'scenes/project/isProjectNameTaken'
import { projectLogic } from 'scenes/projectLogic'
import { teamLogic } from 'scenes/teamLogic'

import { OrganizationType, ProjectType } from '~/types'

export const NAME_TAKEN_REASON =
    'There is already a project with this name in this organization. Choose a different name.'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface teamDisplayNameLogicValues {
    currentOrganization: OrganizationType | null // organizationLogic
    currentProject: ProjectType | null // projectLogic
    draftName: string | null
    name: string
    nameTaken: boolean
    renameDisabledReason: string | null
    trimmedName: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface teamDisplayNameLogicActions {
    updateCurrentTeam: (payload: Partial<import('~/types').TeamType>) => Partial<import('~/types').TeamType> // teamLogic
    updateCurrentTeamSuccess: (
        currentTeam: import('~/types').TeamPublicType | import('~/types').TeamType,
        payload?: Partial<import('~/types').TeamType> | undefined
    ) => {
        currentTeam: import('~/types').TeamPublicType | import('~/types').TeamType
        payload?: Partial<import('~/types').TeamType>
    } // teamLogic
    setDraftName: (draftName: string) => {
        draftName: string
    }
    submitRename: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface teamDisplayNameLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        name: (draftName: string | null, currentProject: ProjectType | null) => string
        trimmedName: (name: string) => string
        nameTaken: (
            trimmedName: string,
            currentProject: ProjectType | null,
            currentOrganization: OrganizationType | null
        ) => boolean
        renameDisabledReason: (
            trimmedName: string,
            currentProject: ProjectType | null,
            nameTaken: boolean
        ) => string | null
    }
}

export type teamDisplayNameLogicType = MakeLogicType<
    teamDisplayNameLogicValues,
    teamDisplayNameLogicActions,
    Record<string, any>,
    teamDisplayNameLogicMeta
>

export const teamDisplayNameLogic = kea<teamDisplayNameLogicType>([
    path(['scenes', 'settings', 'environment', 'teamDisplayNameLogic']),
    connect(() => ({
        values: [projectLogic, ['currentProject'], organizationLogic, ['currentOrganization']],
        actions: [teamLogic, ['updateCurrentTeam', 'updateCurrentTeamSuccess']],
    })),
    actions({
        setDraftName: (draftName: string) => ({ draftName }),
        submitRename: true,
    }),
    reducers({
        // `null` means the field is untouched, so it follows the stored name. A project that
        // resolves after the first render then fills the field instead of leaving it empty.
        draftName: [
            null as string | null,
            {
                setDraftName: (_: string | null, { draftName }: { draftName: string }) => draftName,
                updateCurrentTeamSuccess: () => null,
            },
        ],
    }),
    selectors({
        name: [
            (s) => [s.draftName, s.currentProject],
            (draftName: string | null, currentProject: ProjectType | null): string =>
                draftName ?? currentProject?.name ?? '',
        ],
        trimmedName: [(s) => [s.name], (name: string): string => name.trim()],
        // A rename patches the project, so the uniqueness rule applies to the project's name. That
        // can differ from the environment's name, which is what `teamLogic` holds.
        nameTaken: [
            (s) => [s.trimmedName, s.currentProject, s.currentOrganization],
            (
                trimmedName: string,
                currentProject: ProjectType | null,
                currentOrganization: OrganizationType | null
            ): boolean =>
                isProjectNameTaken(trimmedName, currentOrganization?.projects, {
                    excludeProjectId: currentProject?.id,
                    currentName: currentProject?.name,
                }),
        ],
        renameDisabledReason: [
            (s) => [s.trimmedName, s.currentProject, s.nameTaken],
            (trimmedName: string, currentProject: ProjectType | null, nameTaken: boolean): string | null =>
                (!trimmedName && 'Enter a name') ||
                (!currentProject && 'Loading the project') ||
                (trimmedName === currentProject?.name && "This is already the project's name") ||
                (nameTaken && NAME_TAKEN_REASON) ||
                null,
        ],
    }),
    listeners(({ values, actions }) => ({
        submitRename: () => {
            if (values.renameDisabledReason) {
                return
            }
            actions.updateCurrentTeam({ name: values.trimmedName })
        },
    })),
])
